package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;

/** Exercise production resize placement and frame coalescing without Android stubs. */
public final class NotebookMarkdownPreviewTest {
    public static void main(String[] args)throws Exception {
        String source=new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/NotebookMarkdownPreview.java")),StandardCharsets.UTF_8);
        String fixture=String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;import java.nio.charset.*;public class MarkdownPreviewPlacementFixture {",
            "static class View{static final int VISIBLE=0,INVISIBLE=4;}static class FrameLayout{static class LayoutParams{int width=1,height=1;}}static class Metrics{float density;}static class Resources{final Metrics metrics=new Metrics();Metrics getDisplayMetrics(){return metrics;}}static class Activity{final Resources resources=new Resources();Resources getResources(){return resources;}}",
            "static class Browser{int visibility=View.VISIBLE,posts,placements;float scaleX,scaleY,pivotX,pivotY,x,y,rotation;String javascript;Runnable pending;FrameLayout.LayoutParams params=new FrameLayout.LayoutParams();void evaluateJavascript(String s,Object cb){javascript=s;}Object getLayoutParams(){return params;}void setLayoutParams(FrameLayout.LayoutParams p){params=p;placements++;}void setPivotX(float v){pivotX=v;}void setPivotY(float v){pivotY=v;}void setX(float v){x=v;}void setY(float v){y=v;}void setScaleX(float v){scaleX=v;}void setScaleY(float v){scaleY=v;}void setRotation(float v){rotation=v;}int getVisibility(){return visibility;}void setVisibility(int v){visibility=v;}void removeCallbacks(Runnable r){if(pending==r)pending=null;}void postOnAnimation(Runnable r){posts++;pending=r;}void frame(){Runnable r=pending;pending=null;if(r!=null)r.run();}}",
            "final Activity activity=new Activity();final Browser view=new Browser();NotebookFigure original,current;NotebookViewport viewport;int page,width=640,sentWidth=-1;float scroll;boolean closed,ready=true,requested,placeQueued;int starts;final Runnable placeFrame=()->{placeQueued=false;place();};void startPreview(){starts++;}",
            NotebookWorkspaceActivationTest.method(source,"void update("),NotebookWorkspaceActivationTest.method(source,"private void place("),
            NotebookWorkspaceActivationTest.method(source,"boolean showing("),NotebookWorkspaceActivationTest.method(source,"void hide("),
            "static byte[] pdf(){return \"%PDF-1.4\\nfixture\\n%%EOF\".getBytes(StandardCharsets.UTF_8);}static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void run(){int checks=0;NotebookMarkdown markdown=new NotebookMarkdown(\"text\",false,640,200,pdf(),640,200,pdf(),20,16);NotebookFigure before=NotebookFigure.markdown(UUID.randomUUID(),120,140,200,0,markdown);NotebookViewport viewport=new NotebookViewport(1,600,800,600,800,12);for(float density:new float[]{1f,1.75f,3f}){MarkdownPreviewPlacementFixture f=new MarkdownPreviewPlacementFixture();f.activity.resources.metrics.density=density;NotebookFigure latest=null;for(int i=0;i<40;i++){latest=before.placed(before.x,before.y,200+i*2,100+i);f.update(before,latest,viewport,1,0);}check(f.view.posts==1&&f.view.pending!=null,\"a burst of pointer events queues only one frame\");f.view.frame();check(f.current==latest&&f.view.javascript.equals(\"window.ScriflowMarkdown.previewWidth(\"+f.width+\");\"),\"the frame publishes only the latest width\");float visibleWidth=f.view.params.width*f.view.scaleX,expected=latest.width*viewport.scale(1);check(Math.abs(visibleWidth-expected)<1.5f,\"WebView placement matches the selected block at each density\");float textScale=f.view.scaleX*density,originalScale=before.width/before.markdown.width()*viewport.scale(1);check(Math.abs(textScale-originalScale)<.003f,\"text scale remains constant through a drag\");f.update(before,before,viewport,1,0);f.hide();f.view.frame();check(f.view.pending==null&&f.view.visibility==View.INVISIBLE&&!f.showing(),\"hiding cancels a pending frame\");checks+=5;}System.out.println(\"NotebookMarkdownPreviewPlacement: \"+checks+\" assertions passed (coalesced frames, density, stable text scale and cancellation).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.MarkdownPreviewPlacementFixture",fixture);
    }
}
